"""Author the HarsanyiNet human proofs in small reviewable groups."""
from pathlib import Path
import json
BASE=Path(__file__).resolve().parent
FILE=BASE/'content.json'
D=json.loads(FILE.read_text());R={r['id']:r for r in D['results']}
ZH=r'''固定有限总体 $N$、模型 $v$、输入 $x$ 与输入基线向量 $r$。$x_T$ 在 $T$ 内保留 $x$、在其余坐标取 $r$；$g(T)=v(x_T)$，输出基线 $b=g(\varnothing)$，中心化游戏 $g_0(T)=g(T)-b$。本篇的原 $V(T)$ 对应 $g_0(T)$，原 $I(T)$ 对应 $I_{g_0}(T)$，且 $I(\varnothing)=0$。单元 $j=(l,u)$ 的掩码游戏是 $u_j(T)=z_j(x_T)$，原 $J_j(T)=I_{u_j-u_j(\varnothing)}(T)$。原输入基线 $b_i$ 对应 $r_i$，不要把它与规范输出基线 $b$ 混同。'''
EN=r'''Fix a finite universe $N$, model $v$, input $x$ and input baseline vector $r$. The mask $x_T$ retains $x$ on $T$ and uses $r$ elsewhere. Set $g(T)=v(x_T)$, output baseline $b=g(\varnothing)$ and centered game $g_0(T)=g(T)-b$. The paper's $V(T)$ is $g_0(T)$ and its $I(T)$ is $I_{g_0}(T)$, with empty interaction zero. For unit $j=(l,u)$, set $u_j(T)=z_j(x_T)$; its $J_j(T)$ is the interaction of $u_j-u_j(\varnothing)$. The source's input baseline $b_i$ corresponds to $r_i$, and differs from the canonical scalar output baseline $b$.'''
def step(i,t,b,f='',decl=None,en=None):
 refs=[] if not decl else [dict(declaration=decl,source_path='lean/HarsanyiLib/Harsanyi/Extensions/HarsanyiNetwork.lean' if decl.startswith('Harsanyi.Network') else 'lean/HarsanyiLib/Harsanyi/Extensions/Attribution.lean' if 'factorial' in decl else 'lean/HarsanyiLib/Harsanyi/Core/Properties.lean',scope='actual_definition_or_theorem',explanation_md='此声明验证标出的数学范围；文字原文对齐仍独立核对。')]
 return dict(id=i,title=t,body_md=b,formula_tex=f,justification='',lean_refs=refs),dict(id=i,title=en[0] if en else t,body_md=en[1] if en else b,justification='')
def put(id,title,en_title,formula,overview,en_overview,steps,assumptions=None,en_assumptions=None,shared=(),status='complete',scope='原陈述的全部数学范围；原错式与修正证明分别保留。',en_scope='The complete mathematical statement; printed errors and the repaired proof remain separately available.',decls=(),original=None):
 r=R[id];r.update(title=title,statement_tex=formula,overview=overview,definitions=[dict(id='hnet-fixed-game',body_md=ZH)],assumptions=assumptions or ['有限总体，固定输入、输入基线和推理时的网络参数；所有子集求和均包括空集。'],proof_steps=[x[0] for x in steps],shared_proof_ids=list(shared),rewrite_status=status,alignment_status='agent_checked_full_statement',completion_scope=scope,proof_scope=scope)
 r['translations']['en']=dict(title=en_title,overview=en_overview,assumptions=en_assumptions or ['Finite universe, fixed input and baseline, and network parameters fixed during inference; all subset sums include the empty set.'],definitions=[dict(id='hnet-fixed-game',body_md=EN)],proof_steps=[x[1] for x in steps],completion_scope=en_scope,proof_scope=en_scope)
 r['original_statement_md']='正式PDF '+r['original_label']+'，数学陈述：\n\\['+formula+'\\]\n原量词与定义见对应来源页；此处不修改命题。'
 r['original_statement_source_type']='formal_statement_mathematical_transcription_with_chinese_prose'
 r['translations']['en']['original_statement_md']='Formal PDF, '+r['original_label']+'. Mathematical statement:\n\\['+formula+'\\]\nThe source pages preserve its original quantifiers and definitions; the proposition is not modified.'
 if original:
  r.update(original_proof_md=original,original_proof_source_type='complete_author_mathematical_argument_transcription',source_transcription_status='complete_mathematical_transcription')
 elif r['original_proof_source_type']=='no_local_proof':r['source_transcription_status']='complete_statement_no_local_proof'
 r['lean'].update(declarations=list(decls),status='compiled_pending_report' if decls else 'not_applicable',compiled=False,scope=en_scope)
 return r

put('hnet-centered-definition','Definition 2：中心化游戏与递归交互','Definition 2: centered game and recursive interactions',r'V(T)=v(x_T)-v(x_\varnothing),\quad I(\varnothing)=0,\quad I(S)=V(S)-\sum_{L\subsetneq S}I(L)',
'递归量是中心化输出的 Möbius 系数，不能默认为原模型输出具有零基线。','The recursively defined coefficients are those of the centered game; the raw model output need not have a zero baseline.',[
step('hnet-definition-center','保留两种基线的区别',ZH,en=('Distinguish the input and output baselines',EN)),
step('hnet-definition-recursive','从反演取出最高阶项',r'公共重构给 $g_0(S)=\sum_{L\subseteq S}I_{g_0}(L)$。把唯一最高阶项 $L=S$ 移至左侧得到原递归定义；$S=\varnothing$ 时 $g_0(\varnothing)=0$。反向按集合基数强归纳可见该递归唯一决定每个系数，故与中心化 Möbius 变换相同。',decl='Harsanyi.interaction_recursive',en=('Isolate the top-order term',r'Reconstruction gives $g_0(S)=\sum_{L\subseteq S}I_{g_0}(L)$. Isolating the unique term $L=S$ yields the printed recurrence; at the empty set the centered output is zero. Strong induction on cardinality shows that this recurrence fixes every coefficient uniquely, so it is the centered Möbius transform.'))],shared=['proof-finite-mobius-reconstruction-v2','proof-finite-mobius-uniqueness-v2'],scope='定义及与公共变换的精确对齐；不是新的论文定理。',en_scope='Definition and exact alignment with the public transform, rather than a new paper theorem.',decls=['Harsanyi.interaction_recursive'])
put('hnet-r1-r2','R1/R2：感受野与掩码律','R1/R2: receptive fields and the mask law',r'u_j(T)=c_j\mathbf1_{R_j\subseteq T},\qquad c_j=z_j(x)',
'R1负责全部保留时的值不变，R2负责缺少任何感受野变量时的值为零。','R1 preserves the unit value when its field is retained; R2 makes it vanish when any field variable is missing.',[
step('hnet-r1-full','保留感受野',r'若 $R_j\subseteq T$，则 $x_T$ 和 $x$ 在 $R_j$ 的每个坐标上相同。R1 的量词适用于这两个任意样本，所以 $u_j(T)=c_j$。',en=('Retain the whole field',r'If $R_j\subseteq T$, the masked and original samples agree at every field coordinate. R1 applies to those two samples and gives $u_j(T)=c_j$.')),
step('hnet-r2-missing','缺变量及空感受野',r'若 $R_j\not\subseteq T$，R2给 $u_j(T)=0$。合并得到指示函数形式；$R_j=\varnothing$ 时该形式允许任意常数 $c_j$，R1/R2 本身不强制它为零。这个边界正是 Lemma 1 的反例来源，不能给原命题加非空假设。',en=('Missing variables and the empty field',r'If $R_j\not\subseteq T$, R2 gives zero. Combining the cases yields the indicator form. An empty receptive field allows any constant value under R1/R2 alone; those requirements do not force it to vanish. This is the boundary counterexample to Lemma 1 and cannot be repaired by adding a nonempty-field assumption.'))],scope='原需求的定义与等价掩码形式，包含空感受野。',en_scope='The source requirements and equivalent mask form, including empty receptive fields.')
put('hnet-reconstruction','未编号：中心化交互重构输出差','Unnumbered: centered dividends reconstruct the output difference',r'\forall T\subseteq N,\quad\sum_{S\subseteq T}I(S)=v(x_T)-v(x_\varnothing)',
'把已证的有限重构应用于本篇明确定义的中心化游戏。','Apply finite reconstruction to the explicitly centered game used by the paper.',[
step('hnet-recon-apply','逐项核对公共对象',r'本篇 $V(T)=g_0(T)$，原 $I$ 是 $I_{g_0}$。公共重构对任意实值有限游戏成立，不用光滑性、统计独立性或网络架构假设，因此可在同一 $N$ 上直接应用。',en=('Match the shared objects exactly',r'The source game $V$ is $g_0$ and its dividend is $I_{g_0}$. Shared reconstruction applies to every real-valued finite game without smoothness, independence or architecture assumptions, so instantiate it on this same universe.')),
step('hnet-recon-empty','全部掩码与空集',r'得到每一个 $T$ 的输出差，而不仅是完整输入。$T=\varnothing$ 时只有零空交互。正文写“network output”应读作所定义的中心化reward；若要原输出须在和外加 $v(x_\varnothing)$。',r'v(x_T)=v(x_\varnothing)+\sum_{S\subseteq T}I(S)',en=('Check all masks and the empty set',r'The identity holds at every mask, not merely the full input. At the empty mask the only dividend is zero. The text’s “network output” in this context is the defined centered reward; recovering the raw output requires adding the original baseline outside the sum.'))],shared=['proof-finite-mobius-reconstruction-v2'],decls=['Harsanyi.reconstruction'],original=r'After Definition 2 (PDF page 3), the author states $v(x)-v(x_\varnothing)=\sum_{S\subseteq N}I(S)$. No separate local proof is supplied; this is the immediate recursive-definition consequence.')
put('hnet-shapley-dividend','Theorem 1：经典 Shapley 的交互均分','Theorem 1: classical Shapley as equal dividend allocation',r'\varphi(i)=\sum_{S\subseteq N:\,i\in S}\frac{I(S)}{|S|}',
'从阶乘权重边际定义开始应用共享加权差分定理，均分式是结论。','Start from the factorial-weighted marginal definition and apply the shared weighted finite-difference theorem; the equal-allocation expression is the conclusion.',[
step('hnet-t1-definition','对齐真实 Shapley 定义',r'原 Definition 1 使用 $V=g_0$ 的经典阶乘权重边际和。中心化在每个边际中相消，所以此值亦等于原始游戏 $g$ 的经典 Shapley。固定 $i\in N$，总体基数至少一。',r'\varphi(i)=\sum_{T\subseteq N\setminus\{i\}}\frac{|T|!(|N|-|T|-1)!}{|N|!}\,[g(T\cup\{i\})-g(T)]',decl='Harsanyi.factorialShapley',en=('Match the actual Shapley definition',r'Definition 1 uses the classical factorial-weighted marginal sum for $V=g_0$. Centering cancels in every marginal, so it equals classical Shapley for the raw game $g$. Fix $i\in N$, ensuring a universe of size at least one.')),
step('hnet-t1-weight','使用完整共享卷积证明',r'共享证明先把每个单变量边际重构为包含 $i$ 的交互之和，再交换有限和。对固定 $S\ni i$，所有包含 $S\setminus\{i\}$ 的环境权重和恰为 $1/|S|$；完整阶乘卷积与边界在共享正文中展开，不把这个系数当作前提。',decl='Harsanyi.factorialShapley_eq_dividendAllocation',en=('Use the fully proved shared convolution',r'The shared proof expands each singleton marginal into dividends containing $i$ and exchanges finite sums. For a fixed $S\ni i$, the sum of weights of environments containing $S\setminus\{i\}$ is exactly $1/|S|$. The shared text proves this factorial convolution and its boundaries; the coefficient is not assumed.')),
step('hnet-t1-boundary','分母与出处',r'求和只含 $i\in S$，故每个分母 $|S|$ 都是正整数；空交互不分给任何玩家。该定理在本文明确外引 Harsanyi (1963)，没有本地作者proof block，项目完整共享证明与外引来源分开标识。',en=('Check denominators and source status',r'Every summation set contains $i$, so its cardinality denominator is positive. The empty dividend is allocated to no player. This theorem is explicitly cited to Harsanyi (1963), with no local author proof block; the complete project shared proof is distinguished from that citation.'))],shared=['shared-harsanyi-shapley-dividend'],decls=['Harsanyi.factorialShapley_eq_dividendAllocation'])
put('hnet-readout-linearity','Theorem 2：中心化交互的加权读出','Theorem 2: weighted readout of centered unit dividends',r'I(S)=\sum_j w_jJ_j(S)',
'读出等式对所有掩码成立；先在每个单元去掉自己的空输入值，再使用有限和线性性。','The readout identity holds at every mask; center each unit at its own empty-input value and then use finite linearity.',[
step('hnet-t2-center','输出中心化的真实等式',r'把层/单元二重索引展平成有限集合 $\mathcal J$。原架构 Eq.(2) 在每个 $x_T$ 满足 $g(T)=\sum_jw_ju_j(T)$，特别也在空掩码成立。两式相减得到 $g_0(T)=\sum_jw_j[u_j(T)-u_j(\varnothing)]$，无需每个单元空输入值为零。',r'g_0(T)=\sum_jw_j\bigl(u_j(T)-u_j(\varnothing)\bigr)',en=('Center the readout identity',r'Flatten the layer/unit indices into a finite set of units. Equation (2) holds for every mask, including the empty mask: $g(T)=\sum_jw_ju_j(T)$. Subtract the empty-mask equality to obtain the displayed centered weighted sum. Individual unit baselines need not be zero.')),
step('hnet-t2-expand','交换两层有限和',r'固定 $S$ 展开 $I_{g_0}(S)$，把上一等式代入每个 $T\subseteq S$。乘法分配律及有限和交换把 $w_j$ 提出内和；该内和正是原定义的 $J_j(S)$。这就是全部目标，适用于空集与非空集。',r'\sum_{T\subseteq S}(-1)^{|S|-|T|}\sum_jw_j[u_j(T)-u_j(\varnothing)]=\sum_jw_jJ_j(S)',decl='Harsanyi.Network.interaction_weighted_sum',en=('Exchange the two finite sums',r'Expand $I_{g_0}(S)$ and substitute the centered readout at each $T\subseteq S$. Finite distributivity and exchange move each fixed weight outside the inner alternating sum, which is exactly the paper’s centered unit dividend $J_j(S)$. This proves the whole claim, including the empty set.'))],shared=['shared-harsanyi-linearity'],decls=['Harsanyi.Network.interaction_weighted_sum'])
put('hnet-unit-interaction','Lemma 1：原命题的空感受野反例','Lemma 1: an empty-field counterexample to the original proposition',r'J_j(R_j)=z_j(x),\qquad\forall S\ne R_j,\ J_j(S)=0',
'仅 R1/R2 不能推出空感受野处的中心化交互等于非零单元值；原命题保留并单列反例。','R1/R2 alone do not make an empty-field centered dividend equal a nonzero unit value; preserve the proposition and record its counterexample.',[
step('hnet-lemma-counterexample','原量词中的合法反例',r'取 $R_j=\varnothing$、单元在所有输入上恒为1。R1成立，因为输出不依赖任何变量；R2指示函数乘积为空积1，故 $z_j(x_T)=1=1\cdot1$ 对所有掩码成立。但本篇规定 $J_j(\varnothing)=0$，原第一结论要求它等于1，矛盾。此反例不改命题，也不添非空条件。',r'R_j=\varnothing,\ z_j\equiv1:\quad J_j(R_j)=0\ne1=z_j(x)',decl='Harsanyi.Network.empty_unit_counterexample',en=('Give a counterexample within the original quantifiers',r'Take an empty field and a unit constantly equal to 1. R1 holds because no variable affects it. R2 also holds: its empty product is 1, so every masked value equals the full value times that product. Yet the paper defines the empty centered dividend to be zero, while the first conclusion demands 1. This counterexample preserves the original proposition and adds no nonempty-field premise.')),
step('hnet-lemma-valid-scope','完整说明其可成立边界',r'由 R1/R2 得 $u_j(T)=c_j\mathbf1_{R_j\subseteq T}$。公共纯AND变换给原始交互只在 $R_j$ 为 $c_j$。再中心化：若 $R_j\ne\varnothing$，空输入值为零且原结论成立；若 $R_j=\varnothing$，单元游戏恒定，全部中心化交互为零。这是对反例及作用域的分析，绝不宣称补条件后的命题就是原Lemma。',r'J_j(S)=\begin{cases}0&R_j=\varnothing,\\c_j\mathbf1_{S=R_j}&R_j\ne\varnothing.\end{cases}',decl='Harsanyi.Network.requirement_unit_interaction',en=('Explain the complete valid boundary',r'The requirements give $u_j(T)=c_j\mathbf1_{R_j\subseteq T}$. The pure AND transform has a single raw dividend at the field. Centering leaves this result unchanged for a nonempty field, whose empty output is zero. An empty field instead gives a constant game, and every centered dividend is zero. This analyzes the scope and counterexample; the restricted statement is not claimed as the original lemma.')),
step('hnet-lemma-architecture','架构子结论独立保留',r'Eq.(5)–(7) 还给无偏置线性层；从零基线输入递归可证每个单元的空输入值为零。因此该实际架构中的空感受野单元也是零，原公式在这个架构内成立。它是额外已证明的架构事实，不能回填为只写R1/R2的Lemma前提。',decl='Harsanyi.Network.unit_interaction',en=('Retain the actual architecture subclaim separately',r'The bias-free linear operation in Equations (5)–(7) proves recursively that every unit has zero empty-input output. Thus an empty-field unit in this actual architecture is also zero, and the displayed formula holds there. This is a separately proved architecture fact, not an assumption silently inserted into the lemma that states only R1/R2.'))],status='blocked_by_false_statement',scope='原Lemma命题错误；反例及实际架构可成立子结论均完整，不冒称原命题被证明。',en_scope='The original lemma is false. The counterexample and the valid actual-architecture subclaim are complete; the original proposition is not claimed as proved.',decls=['Harsanyi.Network.empty_unit_counterexample','Harsanyi.Network.requirement_unit_interaction','Harsanyi.Network.unit_interaction'])
put('hnet-forward-shapley','Theorem 3：一次前向传播的精确 Shapley','Theorem 3: exact Shapley values from one forward propagation',r'\varphi(i)=\sum_j\frac{w_jz_j(x)}{|R_j|}\mathbf1_{i\in R_j}',
'经典 Shapley 的求和只分配非空交互。即使原 Lemma 的空集分支错误，常数单元也不给任何玩家归因。','Classical Shapley allocates only nonempty dividends. Even though the lemma’s empty branch is false, a constant unit contributes no player attribution.',[
step('hnet-t3-derive','从经典定义导出均分，再代入读出',r'先用 Theorem1 的真实阶乘到均分桥得到 $\varphi(i)=\sum_{S\ni i}I(S)/|S|$。Theorem2 把每个 $I(S)$ 换为 $\sum_jw_jJ_j(S)$。两层有限和可以交换；所有求和 $S$ 都含 $i$，故非空。',r'\varphi(i)=\sum_jw_j\sum_{S\subseteq N:\,i\in S}\frac{J_j(S)}{|S|}',decl='Harsanyi.Network.requirement_forward_shapley',en=('Derive the allocation formula and substitute the readout',r'Use Theorem 1’s actual factorial-to-dividend bridge, then substitute Theorem 2’s weighted unit-dividend identity. Exchange the two finite sums. Every dividend being allocated contains $i$ and is therefore nonempty.')),
step('hnet-t3-unit','逐单元处理全部感受野',r'若 $i\in R_j$，该场非空，前面完整变换证明只有 $S=R_j$ 贡献 $z_j(x)$，得到 $w_jz_j(x)/|R_j|$。若 $i\notin R_j$，该场的唯一可能非零原交互不在求和范围；空场的中心化交互全部零，所以同样贡献零。这样不需要排除空场。',r'\sum_{S\ni i}\frac{J_j(S)}{|S|}=\begin{cases}z_j(x)/|R_j|&i\in R_j,\\0&i\notin R_j.\end{cases}',en=('Handle every receptive field separately',r'If $i\in R_j$, the field is nonempty and its sole centered dividend is $z_j(x)$ at that field. If $i\notin R_j$, its possible raw field dividend is outside the allocated family; an empty field has only zero centered dividends. Thus the unit contributes zero. No empty-field exclusion is required.')),
step('hnet-t3-denominator','原式的零分母阅读',r'严谨实现把结果写为条件和：仅在 $i\in R_j$ 时计算分式，其他项定义为零。这与第一行 $S\ni i$ 的数学范围相同；原文把 $1/|S|$ 扩到空S且乘零指示，存在未声明的0分母表达，不是新反例。Lean条件分支不读取这个分母；证明的非零分支自动有 $|R_j|>0$。架构实现亦独立核验。',decl='Harsanyi.Network.forward_shapley',en=('Make the printed denominator convention explicit',r'The rigorous conditional sum evaluates the fraction only when the unit field contains $i$ and assigns zero otherwise. This is exactly the domain of the initial sum over $S\ni i$. The printed extension of a reciprocal to empty sets times a zero indicator lacks a division convention; it is an expression issue, not a failure of the valid attribution claim. The Lean branch avoids that denominator and its contributing branch automatically has positive cardinality. The actual architecture adapter is also proved.'))],shared=['shared-harsanyi-shapley-dividend'],decls=['Harsanyi.Network.requirement_forward_shapley','Harsanyi.Network.forward_shapley'])

R['hnet-forward-shapley'].update(statement_assessment='scope_ambiguous',completion_scope='经典Shapley的条件和算法恒等式完整；原全j分式的空场除法约定未明。',proof_scope='经典Shapley的条件和算法恒等式完整；原全j分式的空场除法约定未明。')
R['hnet-forward-shapley']['translations']['en'].update(completion_scope='The conditional-sum algorithm identity for classical Shapley is complete. The printed reciprocal over every unit lacks an empty-field division convention.',proof_scope='The conditional-sum algorithm identity for classical Shapley is complete. The printed reciprocal over every unit lacks an empty-field division convention.')
R['hnet-unit-interaction'].update(statement_assessment='refuted',rewrite_role='counterexample',verification_role='counterexample')
R['hnet-unit-interaction']['lean'].update(evidence_role='counterexample_and_valid_architecture_subclaim',scope='The first declaration refutes the original empty-field claim. The other declarations prove the precise mask-law boundary and the bias-free architecture subclaim, not the original R1/R2-only lemma.')
